  } else if(o.type==='user/message'){
    const b=(o.data.content||[]);
    const txt=b.map(x=>x.text||('['+(x.type||'?')+']')).join(' ').replace(/\n/g,' | ');
    console.log('['+o.seq+'] USER:', txt.slice(0,900));
  } else if(o.type==='turn/start'||o.type==='turn/end'){
    console.log('['+o.seq+'] ===', o.type);
  }
}
