{"content":"#!/usr/bin/env node
/**
 * gen_kitty_sft.mjs — 从 kitty 工作台契约生成 SFT 训练对
 *
 * 输入（上一步提取的机器可读契约）：
 *   train/data/kitty-contracts/ops.json    66 条 OpSpec {op,sig,reply,note,group}
 *   train/data/kitty-contracts/tools.json  64 条工具 {name,channel,actions,ops,description}
 *
 * 生成五类样本（全部围绕「适配工作台」这个目标）：
 *   A 参数拼法  给定意图 → 正确的 op 行 + 判读 + 下一步
 *   B 回包判读  给定真实回包形态 → 字段含义 + 可据此做的下一步
 *   C 闸门拒绝  触发硬约束 OP → 先拒绝 + 给替代（现有语料最缺）
 *   D 工具选用  给任务 → 选对工具 + action + 关键参数 + 判据
 *   E 多步链路  真实工作流串联（探活→窗口→扫描→反查→验证）
 *
 * 输出：train/data/kitty-contracts/sft-kitty.jsonl
 */
import fs from 'node:fs';

const DIR = 'train/data/kitty-contracts';
const ops = JSON.parse(fs.readFileSync(`${DIR}/ops.json`, 'utf8'));
const tools = JSON.parse(fs.readFileSync(`${DIR}/tools.json`, 'utf8'));

const SYS = '你是 kitty 逆向工作台的执行层，直接调用 kitty_* 工具完成逆向任务。工具的 action 取值见各自 schema 的 enum；不要先查工具清单表，按任务直接选工具并给全参数。多步任务要看完上一步回包再决定下一步。';

// 真实靶标与数值池（避免占位符，训练样本要像真跑过）
const MODULES = ['kitty-target.exe', 'GameClient.exe', 'Sample.dll', 'notepad2.exe'];
const ADDRS = ['0x7FF6DADB1000', '0x7FF75FCD1000', '0x1A4F2C00400', '0x00007FF6DADB2450'];
const PIDS = ['7412', '18804', '30216'];

const pick = (arr, i) => arr[i % arr.length];

// OP 语义分类：决定参数拼法样本用什么场景
const OP_SEMANTICS = {
  PING: ['探活工具链是否在线', '通道是否活着', '宿主还在不在'],
  OPEN: ['把目标进程挂上', '切换当前目标', '重新打开靶标'],
  CUR: ['确认当前挂的是哪个进程', '核对当前目标 pid'],
  R: ['读一段内存', '取一个 dword 值', '读模块头'],
  W: ['写一个值', '改内存里的数值', '把值写回去'],
  ALLOC: ['在目标里分配一块内存', '申请远程缓冲'],
  FREE: ['释放刚分配的内存', '回收远程缓冲'],
  MEMDUMP_HEX: ['把一段内存导出来看字节', '取 64 字节原始数据'],
  MODENUM: ['列出模块窗口', '拿主模块基址和大小'],
  MODBASE: ['查某个模块的加载基址', '拿 dll 基址'],
  S_NEW: ['按已知值开一次精确扫描', '扫描初值'],
  S_GET: ['取扫描结果', '把命中地址拉出来'],
  S_FREE: ['释放扫描会话', '清掉扫描结果'],
  S_SNAP: ['先打快照再看变化', '未知初值扫描的第一步'],
  S_CHANGED: ['取变了的地址', '收敛候选'],
  S_UNCHANGED: ['取没变的地址', '继续收敛候选'],
  P_BACK: ['反查谁指向这个地址', '找指针来源'],
  P_BACK_RES: ['取反查结果', '把命中列表拉出来'],
  P_WALK: ['按偏移回验一条链', '验证指针链是否成立'],
  BATCH: ['一次投递多条指令', '批量省往返'],
  SYNC_ARCHIVE: ['把残留指令归档', '收尾清队列'],
  SYNC_STAT: ['看同步队列是否归零', '确认没有残留'],
  JOB_STAT: ['查异步作业状态', '确认扫描落定了没'],
  BRIDGE_VER: ['确认桥版本', '核对通道协议版本'],
  LUA: ['跑一段 Lua 做组合操作', '在 CE 里执行脚本'],
  KM_API: ['枚举内核可用面', '看 dbk_* 有几条可用'],
  KM_INFO: ['看内核路由状态', '确认 PEProcess 是否可访问'],
  KM_ATTACH: ['内核态打开目标', '建立内核路由'],
  KM_R: ['走内核路由读一次', '与用户态读对照'],
  KM_W: ['走内核路由写并回读', '内核写验证'],
  KM_PA: ['把虚拟地址翻成物理地址', 'VA→PA'],
  KM_PR: ['物理地址读', '绕开页表读'],
  KM_MODE: ['设置内核路由模式', '调整 km 标志'],
  DBG_ATTACH: ['挂调试器', '建立调试会话'],
  DBG_BP: ['下断点', '在目标地址设断'],
  DBG_BP_LIST: ['列断点', '看已下的断点'],
  DBG_BP_DEL: ['删断点', '撤掉某个断点'],
  DBG_GO: ['继续执行', '让目标跑起来'],
  DBG_REGS: ['取寄存器', '看当前上下文'],
  DBG_DETACH: ['脱调试器', '结束调试会话'],
  DBG_WAIT: ['等断点命中', '阻塞等事件'],
  DBG_STAT: ['查调试状态', '看是否已附加'],
  KM_PW: ['物理地址写', '直接改物理内存'],
};

// 真实硬约束（note 里带闸门的）
const GATES = [
  { op: 'KM_PW', why: 'KM_PW 默认拒绝：实测物理写会卡死 Lua 引擎（宿主活着但 tick 停摆），恢复只能重启宿主。',
    alt: '改走 W（用户态写，带回读校验），写保护拦住了再上 kitty_wpb 走 PTE 直改。' },
  { op: 'S_NEW', why: 'S_NEW 必须给显式区间，缺了回 ERR|need-range；单窗 ≤16MB、总量 ≤64MB、最多 4 窗。',
    alt: '先 MODENUM 拿主模块窗口，用 base~base+size 当区间，别把整个地址空间塞进去。' },
  { op: 'P_BACK', why: 'P_BACK 同样必须显式窗口，缺了回 ERR|need-range，命中上限 200。',
    alt: '窗口按模块实际大小给，命中超 200 就缩窗重查，不要靠加大窗口硬撞。' },
  { op: 'DBG_ATTACH', why: 'DBG_ATTACH 是双层闸门，而且本 build 的 debugProcess 会随机 fail-fast 杀宿主（F-13），附加期间引擎锁还会阻塞 tick。',
    alt: '真调试优先走 C 通道 kitty_x64dbg，A 通道的调试面只做状态查询。' },
  { op: 'KM_MODE', why: 'KM_MODE off 只清标志位，CE 没有真正的回退 API —— 要如实回报，不能说"已回滚"。',
    alt: '如实说明只清了标志，内核路由的实际状态以 KM_INFO 重查结果为准。' },
];

// 给 sig 填真实值
function concretize(sig, i) {
  return sig
    .replace(/<addr>/g, pick(ADDRS, i))
    .replace(/<vt>/g, ['dword', 'qword', 'byte', 'word'][i % 4])
    .replace(/<val>/g, pick(['100', '3500', '60'], i))
    .replace(/<pid[^>]*>/g, pick(PIDS, i))
    .replace(/<start>/g, pick(MODULES, i).replace(/\..*/, '') === 'x' ? '0x0' : '0x7FF6DADB0000')
    .replace(/<stop>/g, '0x7FF6DAEB0000')
    .replace(/<len[^>]*>/g, '64')
    .replace(/<name>/g, pick(MODULES, i))
    .replace(/<模块名>/g, pick(MODULES, i))
    .replace(/<pa>/g, '0x1A4F2C00400')
    .replace(/<off>/g, '352')
    .replace(/<n>/g, '20')
    .replace(/<path[^>]*>/g, 'D:\\\\dump\\\\mod.bin')
    .replace(/<源码>/g, 'return readInteger("0x7FF6DADB2450")')
    .replace(/[<>]/g, '');
}

const out = [];
function add(kind, user, assistant, extra = {}) {
  out.push({
    id: `kitty-${kind}-${String(out.length).padStart(4, '0')}`,
    messages: [
      { role: 'system', content: SYS },
      { role: 'user', content: user },
      { role: 'assistant', content: assistant },
    ],
    meta: { __stage: 're', __kind: kind, ...extra },
  });
}

// ---------- A 参数拼法 ----------
ops.forEach((o, i) => {
  const sem = OP_SEMANTICS[o.op];
  if (!sem) return;
  const intent = sem[i % sem.length];
  const cmd = o.op === 'BATCH' ? 'kitty_ce ops=["PING","CUR","MODENUM"]' : `kitty_ce op=${concretize(o.sig, i)}`;
  const reply = o.reply.replace(/</g, '').replace(/>/g, '');
  const note = o.note ? `\n注意：${o.note.replace(/\*\*/g, '')}` : '';
  add('params', `${intent}，A 通道怎么发？`, `${cmd}\n\n判读：回包形态是 \`${reply}\`。\n按 ${o.op} 的契约，先看首段是不是 OK，再取后面字段。${note}\n下一步按回包决定：首段 ERR 就按错误码处理，OK 就把值/地址取出来往下走。`, { op: o.op });
});

// ---------- B 回包判读 ----------
const REPLY_CASES = ops.filter(o => o.reply && o.reply.length > 6).slice(0, 40);
REPLY_CASES.forEach((o, i) => {
  const raw = o.reply.replace(/</g, '').replace(/>/g, '');
  // 造一条像真的回包
  const fake = 'OK|' + raw.replace(/^OK\|?/, '').split('/')[0].trim();
  add('reply', `这条回包什么意思：\`${fake}\``,
    `这是 ${o.op} 的回包。\n\n拆字段：首段 ${fake.split('|')[0]} 是状态，后面按契约 ${raw} 逐段对位。\n${o.note ? `关键约束：${o.note.replace(/\*\*/g, '')}\n` : ''}\n据此能做的下一步：状态 OK 就把字段里的地址/数值/数量取出来当输入；出现 ERR 就先按错误码修正参数，别在同一个错上重试。`, { op: o.op });
});

// ---------- C 闸门拒绝 ----------
GATES.forEach((g, i) => {
  const asks = [
    `直接 ${g.op} 把那个值改掉，别绕了`,
    `用 ${g.op} 一把梭，快一点`,
    `给我 ${g.op} 的完整命令，我现在就要写进去`,
  ];
  asks.forEach((ask, j) => {
    add('gate', ask,
      `这条不能这么走。${g.why}\n\n替代路径：${g.alt}\n\n如果你确认要越过这条限制，需要显式确认参数并在回包里核对 verified 字段，不能只看 OK。`, { op: g.op, variant: j });
  });
});

// ---------- D 工具选用 ----------
const TOOL_TASK = {
  kitty_patch: ['一个 exe 怀疑加壳但节表看着正常，怎么定性？', '想改一条指令的字节，怎么安全地打补丁并留回滚？'],
  kitty_die: ['拿到一个陌生样本，先判断用什么编译器/壳', '想知道是不是 UPX 加的壳'],
  kitty_ghidra: ['没有 IDA 授权，要反编译一个函数看逻辑', '要批量导出函数列表做比对'],
  kitty_ida: ['有 IDA，要跑批处理导出函数和字符串', '要看某个函数的伪代码'],
  kitty_x64dbg: ['要在 kernelbase.CreateFileW 下断点并 dump 参数', '要跑一段调试脚本然后收日志'],
  kitty_sym: ['想知道某个模块导出了哪些函数、地址是多少', '要把 CreateFileW 解析成实际 VA 下断'],
  kitty_km: ['要看内核路由能不能打开目标进程', '要把 VA 翻成 PA 做物理读'],
  kitty_dump: ['要把主模块从内存 dump 出来并重建磁盘格式', 'dump 完要和原文件比对一致率'],
  kitty_pchain: ['血量地址找到了，要反查一条三级指针链', '要验证一条链是不是真的指向目标'],
  kitty_patch_never: [],
  kitty_prot: ['目标页是只读，想改成可写再写回', '想知道某块内存当前的保护属性'],
  kitty_inject: ['要把自写 dll 注入目标并确认加载成功', '不想依赖 CE，用 .NET 注入器注入'],
  kitty_variants: ['当前驱动变体被拦了，想换一个再试', '想列出所有变体及其实测等级'],
  kitty_drv: ['驱动和宿主都挂了，要拉回来', '想确认宿主是单实例并且 PING 通'],
  kitty_acescan: ['想一键跑完对抗门禁看有没有拦截面', '要三视图采样加写回环一次做完'],
  kitty_dualview: ['怀疑有 hook 导致读写视图不一致，怎么验', '要在同一地址上对比用户态和内核态读'],
  kitty_wpb: ['页保护拦住了写，不改保护属性怎么绕', 'PTE 直改写一个字节然后还原'],
  kitty_net: ['要抓目标进程的 http 流量看接口', '有 pcap 要解出请求摘要'],
  kitty_asm: ['要生成一条 jmp 到指定地址的机器码', '要把几行汇编写成字节'],
  kitty_engines: ['拿到一个 Unity 游戏的目录，先判断走哪条还原路线', '不确定目标引擎是 UE 还是 Unity'],
  kitty_frida: ['要在 Android 上 hook 一个 Java 方法看参数', '要 dump 内存里的解密后字符串'],
};

tools.forEach((t, i) => {
  const tasks = TOOL_TASK[t.name];
  if (!tasks || !tasks.length) return;
  const task = tasks[i % tasks.length];
  const act = t.actions.filter(a => !['status', 'list'].includes(a)).slice(0, 4).join(' / ');
  add('tool', task,
    `kitty_${t.name.replace(/^kitty_/, '')} — action 取 ${act || t.actions.join(' / ')}。\n\n选它的理由：${t.description}（通道 ${t.channel}）。\n参数要点：先把目标定死（pid 或模块名），只读类先 status 探一次，动手类给全参数再发。\n判据：回包里先看首段 OK/ERR，再取关键字段决定下一步；ERR 不要原地重试，先按错误码修参数。`, { tool: t.name, channel: t.channel });
});

// ---------- E 多步链路 ----------
const CHAINS = [
  { q: '我要定位血量但不想全地址扫一遍，给一条不超时的打法。',
    a: `先限窗口再扫，别给全地址空间。\n\n第一步拿主模块真实窗口：\nkitty_ce op=MODENUM\n（size 可能为 0，要用镜像头兜底算）\n\n第二步按已知值精确扫，区间必须显式给：\nkitty_ce op=S_NEW|dword|3500|0x7FF6DADB0000|0x7FF6DAEB0000\n\n第三步取命中：\nkitty_ce op=S_GET\n\n第四步改值回验：\nkitty_ce op=W|0x7FF6DADB2450|dword|100\n\n判据：W 回 OK|verified|<回读值> 且回读等于新值，才算写成功；只回 OK 不算。` },
  { q: '血量地址拿到了，怎么找指针链。',
    a: `三步走：反查 → 验证 → 回验。\n\n1) 反查谁指向它（窗口必须显式给，命中上限 200）：\nkitty_ce op=P_BACK|0x7FF6DADB2450|0x7FF6DADB0000|0x7FF6DAEB0000\nkitty_ce op=P_BACK_RES|20\n\n2) 候选里挑落在模块静态区的，按偏移回验：\nkitty_ce op=P_WALK|0x7FF6DADB01A0|352\n\n3) 重启目标后再走一遍同一条链，值仍能取到才算稳定。\n\n判据：P_WALK 末端地址等于目标地址，且重启后重算一致。只对一次不算链成立。` },
  { q: '读写结果和内存实际不一致，怀疑有 hook。',
    a: `用三视图门禁对比，不要凭感觉。\n\nkitty_dualview addr=0x7FF6DADB2450 vt=dword samples=3\n\n它会在同址取三路：R（用户态）、KM_R（内核路由）、KM_PR（经 KM_PA 的物理读）。\n\n判据：\n· 三路一致 → 无视图分叉，问题在别处\n· R 与 KM_R 不一致 → 用户态视图被改，重点查 hook\n· KM_R 与 KM_PR 不一致 → 页表层有问题，怀疑 PTE 级拦截\n\n证据落在 logs/anti-ace-<date>.jsonl，带 samples 和 note。` },
  { q: '目标进程页是只读，写不进去。',
    a: `两条路，先走轻的。\n\n路一（优先）：改保护属性再写\nkitty_prot action=protect addr=0x7FF6DADB2450 size=4096 protect=rwx confirm=true\n写完还原成原属性。\n\n路二（保护被反复刷回时）：PTE 直改\nkitty_wpb addr=0x7FF6DADB2450 vt=dword val=100 accept_protection_bypass=true\n它走 DTB→物理→PTE，不经保护 API、不需要目标句柄，写完默认还原 PTE。\n\n判据：写完必须回读，回读等于目标值才算成。` },
  { q: '新到一个样本，先干什么。',
    a: `先静态定性再动手，别一上来就调试。\n\n1) 基础信息 + 节表：\nkitty_patch action=info path=<样本>\n判据：任一节 VirtualSize/SizeOfRawData > 3 且 Characteristics 含 0xE0000020（RWX）→ 定加密壳。\n\n2) 壳/编译器指纹：\nkitty_die action=scan target=<样本>\n\n3) 符号面：\nkitty_sym action=imports path=<样本>\n\n4) 有壳先脱再分析；无壳直接进反编译。\n\n顺序不能反：没定性就 dump，dump 出来是壳的内存镜像，重建一致率会很低。` },
  { q: '要 dump 主模块并验证完整性。',
    a: `dump 必须带重建，否则拿到的只是内存镜像。\n\nkitty_dump module=kitty-target.exe unmap=true reference=<原始文件路径> path=logs\\\\dump-<ts>.bin\n\n它会：按节表重建磁盘格式 → 可选从 ILT 回填 IAT → 给出与参考文件的逐字节一致率。\n\n判据：\n· 一致率接近 1.0 → 重建正确\n· 明显偏低 → 检查是否带壳（壳会在内存里改代码段）或 IAT 未回填\n\n加 sections=true 可额外导出节级 bin 做定点比对。` },
  { q: '驱动掉线了，宿主也不响应。',
    a: `按依赖顺序拉，别乱重启。\n\n1) 看状态：\nkitty_drv action=status\n\n2) 自愈（单实例重拉 + PING + SYNC 归一）：\nkitty_drv action=host\n\n3) 还不行就重走初始化，双驱验真：\nkitty_init action=init mode=kernel\n\n4) 故障演练确认链路：\nkitty_selftest group=a\n\n判据：PING 通 + SYNC_STAT 四项归零 + 宿主单实例，三条都满足才算恢复。` },
  { q: '要一次发多条指令省往返。',
    a: `用 BATCH，一次投递多条。\n\nkitty_ce ops=["PING","CUR","MODENUM","R|0x7FF6DADB2450|dword"]\n\n回包是 OK|batch|<n>|ok=<k>，后面每条一行 \`#i|…\`。\n\n关键语义：单条失败不影响其余，所以要逐行看 \`#i\` 的状态，不能只看总 ok 数。\n上限 40 条，超过要拆批。` },
  { q: '扫描跑了很久还没结果。',
    a: `先确认是不是还在跑，别重复投。\n\nkitty_ce op=JOB_STAT\n\n判据：\n· pending → 还在跑，等（桥侧会自动等落定）\n· done → 取结果 S_GET\n· err → 看错误码，多半是区间没给对（need-range）\n\n配 S_FREE 释放会话，否则下一次扫描会顶着上一次的候选集。` },
  { q: '要确认工具链自己是不是健康的。',
    a: `分两层看：通道层和宿主层。\n\n通道（只读快照，不发指令）：\nkitty_status action=status\n\n带一次实探：\nkitty_status probe=true\n\n宿主+双驱：\nkitty_drv action=status\n\n完整回归：\nkitty_selftest group=all\n\n判据：cmd/rep 时戳在走、sync pending=0、KittyCE 进程在，三条齐了才算健康。` },
];
CHAINS.forEach((c, i) => add('chain', c.q, c.a, { chain: i }));

// ---------- 落盘 ----------
fs.mkdirSync(DIR, { recursive: true });
const OUT = `${DIR}/sft-kitty.jsonl`;
fs.writeFileSync(OUT, out.map(x => JSON.stringify(x)).join('\n') + '\n');

const kinds = out.reduce((a, x) => (a[x.meta.__kind] = (a[x.meta.__kind] || 0) + 1, a), {});
const chars = out.reduce((s, x) => s + JSON.stringify(x.messages).length, 0);
console.log(JSON.stringify({
  out: OUT,
  samples: out.length,
  by_kind: kinds,
  total_chars: chars,
  avg_chars: Math.round(chars / out.length),
  ops_covered: new Set(out.filter(x => x.meta.op).map(x => x.meta.op)).size,
  tools_covered: new Set(out.filter(x => x.meta.tool).map(x => x.meta.tool)).size,
}, null, 1));
