{"content":"#!/usr/bin/env node
/**
 * extract_drce_tools.mjs — 从 kitty 工具实现提取参数级契约（只读 DrCE）
 *
 * 比 tool-manifest 更细一层：defineTool 里每个 parameters 的 description
 * 带真实约束（默认值/上限/枚举/互斥），这是「怎么调用」的直接来源。
 *
 * 解析策略：定位 defineTool({ 起点 → 括号配平找到对象结尾 → 在块内提取
 *   name / description / parameters.<key>.description / parameters.<key>.type
 *
 * 输出：train/data/re-iter/drce-tools-deep.json
 */
import fs from 'node:fs';
import path from 'node:path';

const SRC_DIRS = [
  'D:/DrCE(26.2.16)/kitty-toolbox/src/tools',
  'D:/DrCE(26.2.16)/kitty-toolbox/src',
];
const OUT = 'train/data/re-iter/drce-tools-deep.json';

/** 从 startIdx（指向 '{'）开始配平，返回匹配的 '}' 下标 */
function matchBrace(text, startIdx) {
  let depth = 0, inStr = null, esc = false;
  for (let i = startIdx; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === inStr) inStr = null;
      continue;
    }
    if (c === "'" || c === '"' || c === '`') { inStr = c; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

/** 在对象文本里按顶层逗号切分（忽略嵌套与字符串） */
function splitTopLevel(body) {
  const parts = [];
  let depth = 0, inStr = null, esc = false, buf = '';
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (inStr) {
      buf += c;
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === inStr) inStr = null;
      continue;
    }
    if (c === "'" || c === '"' || c === '`') { inStr = c; buf += c; continue; }
    if (c === '{' || c === '[' || c === '(') depth++;
    if (c === '}' || c === ']' || c === ')') depth--;
    if (c === ',' && depth === 0) { parts.push(buf); buf = ''; continue; }
    buf += c;
  }
  if (buf.trim()) parts.push(buf);
  return parts;
}

function unq(s) {
  return String(s).trim().replace(/^['"`]|['"`]$/g, '');
}

/** 提取 parameters 对象里的每个字段 */
function parseParams(text, startIdx) {
  const end = matchBrace(text, startIdx);
  if (end < 0) return [];
  const body = text.slice(startIdx + 1, end);
  const out = [];
  for (const part of splitTopLevel(body)) {
    // key: { type: 'x', description: 'y' }  或  key?: { ... }
    const m = part.match(/^\s*(\w+)\??\s*:\s*\{/);
    if (!m) continue;
    const key = m[1];
    const braceIdx = part.indexOf('{', m[0].length - 1);
    const objEnd = matchBrace(part, braceIdx);
    const inner = objEnd > 0 ? part.slice(braceIdx + 1, objEnd) : part;
    const type = (inner.match(/type:\s*'([^']+)'/) || [, ''])[1];
    const desc = (inner.match(/description:\s*'((?:[^'\\]|\\.)*)'/) || [, ''])[1]
      .replace(/\\'/g, "'");
    const enums = [...inner.matchAll(/enum:\s*\[([^\]]*)\]/g)]
      .flatMap(x => x[1].split(',').map(s => unq(s))).filter(Boolean);
    out.push({ name: key, type, description: desc, enum: enums });
  }
  return out;
}

const tools = [];
for (const dir of SRC_DIRS) {
  if (!fs.existsSync(dir)) continue;
  for (const name of fs.readdirSync(dir)) {
    if (!name.endsWith('.ts')) continue;
    const fp = path.join(dir, name);
    if (!fs.statSync(fp).isFile()) continue;
    const text = fs.readFileSync(fp, 'utf8');
    let idx = 0;
    while ((idx = text.indexOf('defineTool({', idx)) >= 0) {
      const braceIdx = text.indexOf('{', idx);
      const end = matchBrace(text, braceIdx);
      if (end < 0) break;
      const block = text.slice(braceIdx, end + 1);
      const nm = (block.match(/name:\s*'([^']+)'/) || [])[1];
      if (!nm) { idx = end + 1; continue; }
      const desc = (block.match(/description:\s*'((?:[^'\\]|\\.)*)'/) || [, ''])[1].replace(/\\'/g, "'");
      // parameters: { ... }
      const pIdx = block.indexOf('parameters:');
      let params = [];
      if (pIdx >= 0) {
        const pBrace = block.indexOf('{', pIdx);
        if (pBrace > 0) params = parseParams(block, pBrace);
      }
      // 从实现的 if (act === 'xxx') 提取真实 action 分支（比 manifest 准）
      const acts = [...block.matchAll(/(?:act|action)\s*===\s*'([^']+)'/g)].map(m => m[1]);
      tools.push({
        name: nm,
        file: name,
        description: desc,
        params,
        action_branches: [...new Set(acts)],
      });
      idx = end + 1;
    }
  }
}

// 去重（同名工具只留参数最多的一份）
const best = new Map();
for (const t of tools) {
  const prev = best.get(t.name);
  if (!prev || t.params.length > prev.params.length) best.set(t.name, t);
}
const uniq = [...best.values()].sort((a, b) => a.name.localeCompare(b.name));

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, JSON.stringify(uniq, null, 1), 'utf8');

const totalParams = uniq.reduce((s, t) => s + t.params.length, 0);
const withDesc = uniq.reduce((s, t) => s + t.params.filter(p => p.description).length, 0);
console.log(JSON.stringify({
  out: OUT,
  tools: uniq.length,
  total_params: totalParams,
  params_with_description: withDesc,
  desc_coverage: +(withDesc / Math.max(totalParams, 1)).toFixed(3),
  tools_with_action_branches: uniq.filter(t => t.action_branches.length).length,
  sample: uniq.slice(0, 3).map(t => ({ name: t.name, params: t.params.length, actions: t.action_branches.length })),
}, null, 1));
