async function pWalk(c: Ctx, base: number): Promise<number | null> {
  const rep = await call(c, `P_WALK|${fmt(base)}|0`)
  if (!rep.startsWith('OK|')) return null
  try { return hx((rep.split('|')[1] ?? '').trim()) } catch { return null }
}

export async function pchain(fn: BridgeFn, targetHex: string, opts: PChainOpts | number = {}, modArg?: string): Promise<PChainResult> {
  const o: PChainOpts = typeof opts === 'number' ? { depth: opts, mod: modArg } : opts
  const depth = o.depth ?? 2
  const mod = o.mod ?? 'kitty-target.exe'
  const maxVerify = o.maxVerify ?? 24
  const frontierCap = o.frontierCap ?? 8
  const hitsPerParent = o.hitsPerParent ?? 200
  const maxKeep = o.maxKeep ?? 32
  const c: Ctx = {
    call: fn, timeout: o.timeoutMs ?? 20000, calls: 0, verified: 0, candidates: 0,
    truncated: false, pendingWaits: 0, notes: [],
  }
  const t0 = Date.now()
  const target = hx(targetHex)

  /* ---- 窗口解析：显式 > MODENUM(size>0) > MODENUM base+镜像 SizeOfImage > MODBASE + 16MB 兜底 ---- */
  let start: number
  let stop: number
  let base: number | null = null
  let size: number | null = null
  let source: WindowResolution['source'] = 'explicit'
  try {
    const w = await resolveModuleWindow(fn, mod, c.timeout, { start: o.start, stop: o.stop })
    start = w.start; stop = w.stop; base = w.base; size = w.size; source = w.source
    if (source === 'MODENUM+PE') c.notes.push(`MODENUM 的 size=0 → 用镜像头 SizeOfImage 推导窗口 0x${(size ?? 0).toString(16).toUpperCase()}`)
    if (source === 'MODBASE-fallback') c.notes.push(`MODENUM 未命中 '${mod}' → MODBASE fallback，窗口按 16MB 兜底`)
  } catch (e) {
    c.notes.push(String((e as Error)?.message ?? e))
    return {
      target: fmt(target), module: null, keep: [], droppedStack: [], droppedBad: [], frontier: [],
      stats: {
        calls: c.calls, ms: Date.now() - t0, verified: 0, candidates: 0, truncated: false,
        backPendingWaits: c.pendingWaits, maxVerify, window: null,
      },
      notes: c.notes,
    }
  }
  const inRegion = (a: number): string =>
    base === null ? 'UNKNOWN' : (start <= a && a < stop ? 'STATIC' : 'OTHER')

  const keep: PChainHit[] = []
  const droppedStack: PChainHit[] = []
  const droppedBad: PChainHit[] = []
  let frontier: number[] = [target]
  let truncated = false

  for (let d = 1; d <= depth; d++) {
    const nxt: number[] = []
    const seen = new Set<number>()
    for (const parent of frontier.slice(0, frontierCap)) {
      const cands = await pBackRaw(c, parent, start, stop)
      const list = cands.slice(0, hitsPerParent)
      if (cands.length > hitsPerParent) { truncated = true; c.notes.push(`hop${d} 父 ${fmt(parent)} 命中 ${cands.length} > ${hitsPerParent}，已截断`) }
      let verifiedHere = 0
      for (const cand of list) {
        if (seen.has(cand)) continue
        seen.add(cand)
        if (verifiedHere >= maxVerify) { truncated = true; c.notes.push(`hop${d} 父 ${fmt(parent)} 验证达上限 ${maxVerify}，剩余候选未验`) ; break }
        verifiedHere++
        c.candidates++
        const rec: PChainHit = { addr: fmt(cand), parent: fmt(parent), hop: d, region: inRegion(cand) }
        const hv = await rQword(c, cand)
        c.verified++
        if (hv !== parent) { droppedBad.push(rec); continue }
        const fw = await pWalk(c, cand)
        if (fw !== parent) { droppedBad.push(rec); continue }
        if (rec.region === 'STATIC' || base === null) {
          keep.push(rec)
          nxt.push(cand)
        } else droppedStack.push(rec)
        if (keep.length >= maxKeep) { truncated = true; c.notes.push(`命中达上限 ${maxKeep}，提前收口`); break }
      }
      if (nxt.length >= frontierCap || keep.length >= maxKeep) break
    }
    if (!nxt.length || keep.length >= maxKeep) { frontier = nxt; break }
    frontier = nxt.slice(0, frontierCap)
  }

  return {
    target: fmt(target),
    module: { name: mod, base: base === null ? null : fmt(base), size: size === null ? null : '0x' + size.toString(16).toUpperCase() },
    keep, droppedStack, droppedBad,
    frontier: frontier.map(fmt),
    stats: {
      calls: c.calls, ms: Date.now() - t0, verified: c.verified, candidates: c.candidates,
      truncated, backPendingWaits: c.pendingWaits, maxVerify,
      window: { start: fmt(start), stop: fmt(stop), source },
    },
    notes: c.notes,
  }
}

/** 文本版（旧调用面：单行进、单行出） */
export async function pchainText(call: BridgeCall, targetHex: string, depth = 2, mod = 'kitty-target.exe'): Promise<string> {
  const r = await pchain(call, targetHex, { depth, mod })
  return JSON.stringify(r, null, 2)
}

