import { appendFileSync } from 'node:fs'
import { join } from 'node:path'
import { bridgeCall, channel, ensureHost, hostPid, logHostIncident, sleep } from '../host-utils.js'
import { callText } from '../bridge.js'
import { catalogText } from '../ops-catalog.js'
import type { Ctx, ToolDeps } from './deps.js'

export function registerKernelTools(ctx: Ctx, deps: ToolDeps): void {
  const { defineTool } = deps
  const { live, drvGuard, bram } = deps

  /* ---------------- 三视图门禁（P4-T4.1/4.2）：用户态 / 内核路由 / 物理 ---------------- */
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'kitty_dualview',
    description: '三视图门禁：同址取 R / KM_R / KM_PR（经 KM_PA），差异=视图分叉，落 logs/anti-ace-<date>.jsonl',
    parameters: {
      addr: { type: 'string', required: true, description: '目标虚拟地址（0x…）' },
      vt: { type: 'string', description: 'byte|word|dword|qword|bytes:N（默认 dword）' },
      samples: { type: 'number', description: '连续采样次数（默认 1，上限 20）' },
      note: { type: 'string', description: '本轮备注（写入证据行）' },
      timeout_ms: { type: 'number', description: '超时毫秒（默认 20000）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }],
    },
    async execute(args: { addr: string; vt?: string; samples?: number; note?: string; timeout_ms?: number }) {
      const g = drvGuard()
      const ch = channel(live.kittyDir)
      const tmo = args.timeout_ms ?? live.timeoutMs
      const vt = args.vt ?? 'dword'
      const n = Math.max(1, Math.min(args.samples ?? 1, 20))
      const parse = (r: string): string | null => (r.startsWith('OK|') ? r.split('|').slice(1).join('|') : null)
      const rows: string[] = []
      let diverged = 0
      let kmDegraded = 0
      for (let i = 1; i <= n; i++) {
        const u = parse(await bridgeCall(live.kittyDir, `R|${args.addr}|${vt}`, tmo))
        let k = parse(await bridgeCall(live.kittyDir, `KM_R|${args.addr}|${vt}`, tmo))
        if (k === null) {
          kmDegraded++
          const fb = parse(await bridgeCall(live.kittyDir, `R|${args.addr}|${vt}`, tmo))
          if (fb !== null) k = fb
        }
        const paRep = await bridgeCall(live.kittyDir, `KM_PA|${args.addr}`, tmo)
        const paVal = /pa=0x([0-9A-Fa-f]+)/.exec(paRep)?.[1] ?? null
        const ph = paVal ? parse(await bridgeCall(live.kittyDir, `KM_PR|0x${paVal}|${vt}`, tmo)) : null
        const fork = (u !== null && k !== null && u !== k) || (k !== null && ph !== null && k !== ph)
        if (fork) diverged++
        rows.push(`#${i} addr=${args.addr} pa=${paVal ? '0x' + paVal : 'n/a'} 用户态=${u ?? 'ERR'} 内核=${k ?? 'ERR'} 物理=${ph ?? 'ERR'} ${fork ? '<< 分叉' : '一致'}`)
        try {
          appendFileSync(join(live.root, 'logs', `anti-ace-${new Date().toISOString().slice(0, 10)}.jsonl`),
            JSON.stringify({ ts: new Date().toISOString(), addr: args.addr, vt, pa: paVal, user: u, kernel: k, phys: ph, fork, note: args.note ?? '' }) + '\n', 'utf8')
        } catch { /* 忽略 */ }
        if (n > 1) await sleep(250)
      }
      void ch
      if (kmDegraded > 0) rows.push(`降级 ${kmDegraded}/${n} 轮KM无回包→R兜底（只读降级，禁KM_PW/A-attach）`)
      return (g ? g + '\n' : '') + [`[dualview] samples=${n} 分叉=${diverged} 降级=${kmDegraded} 判据=一致路径`, ...rows].join('\n')
    },
  })), '@dsh-external/kitty-toolbox: kitty_dualview')

  /* ---------------- 内核面（P0）：Dbgk / 物理内存 ---------------- */
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'kitty_km',
    description: '内核面（Dbgk）：api（枚举 dbk_*）| info | attach（内核态打开）| read/write（KM_R/KM_W）| pa（VA→PA）| pread（物理读）| pwrite（永久拒绝：卡死 Lua）',
    parameters: {
      action: { type: 'string', required: true, description: 'api|info|attach|read|write|pa|pread|pwrite' },
