      const g = drvGuard()
      const ch = channel(live.kittyDir)
      const tmo = args.timeout_ms ?? live.timeoutMs
      const vt = args.vt ?? 'dword'
      const a = args.action.toLowerCase()
      try {
        let op = ''
        if (a === 'api') op = 'KM_API'
        else if (a === 'info') op = 'KM_INFO'
        else if (a === 'attach') { if (!args.pid) return 'ERR|attach 需要 pid'; if (bram.kmAttachedPid === args.pid) return (g ? g + '\n' : '') + `KM_ATTACH|${args.pid} → 跳过（attach-once 命中 pid=${bram.kmAttachedPid}，高频重复诱发宿主丢失）`; op = `KM_ATTACH|${args.pid}` }
        else if (a === 'read') { if (!args.addr) return 'ERR|read 需要 addr'; op = `KM_R|${args.addr}|${vt}` }
        else if (a === 'write') { if (!args.addr || args.val === undefined) return 'ERR|write 需要 addr 与 val'; op = `KM_W|${args.addr}|${vt}|${args.val}` }
        else if (a === 'pa') { if (!args.addr) return 'ERR|pa 需要 addr'; op = `KM_PA|${args.addr}` }
        else if (a === 'pread') { if (!args.pa) return 'ERR|pread 需要 pa'; op = `KM_PR|${args.pa}|${vt}` }
        else if (a === 'pwrite') {
          // P4.4：KM_PW 全入口永久拒绝（门禁层先拒；执行层纵深拒，accept 旗不再放行）。
          logHostIncident(live.root, 'km-pwrite-blocked', { pa: args.pa ?? '', vt, pid: hostPid() })
          return (g ? g + '\n' : '') + 'ERR|KM_PW-DENIED:物理写永久拒绝（实测卡死 Lua 引擎）；取证改走 pread 物理读 + R/KM_R 对照'
        } else return `ERR|unknown action: ${args.action}`
        const r = await ch.call(op, tmo)
        if (a === 'attach' && r.ok) bram.kmAttachedPid = Number(args.pid ?? 0) || bram.kmAttachedPid
        const out = [`${op} → ${r.reply}`]
        if (a === 'read' && !r.ok) {
          try {
            const fb = await ch.call(`R|${args.addr}|${vt}`, tmo)
            out.push(`降级 R|${args.addr}|${vt} → ${fb.reply}（KM失败只读降级，禁KM_PW/A-attach）`)
